const sd = $getWorkflowStaticData('global');
sd.processed = sd.processed || [];
const out = [];
for (let i = 0; i < items.length; i++) {
  const client = $('Split Into Items').itemMatching(i).json;
  const files = items[i].json.files || [];
  for (const f of files) {
    if (sd.processed.includes(f.id)) continue;
    out.push({ json: { docId: f.id, docName: f.name, client_id: client.id, client_name: client.name, slug: client.slug } });
  }
}
return out;

const sd = $getWorkflowStaticData('global');
sd.processed = sd.processed || [];
const src = $('Flatten Docs').item.json;
let out = { action: 'skip', client_id: src.client_id, client_name: src.client_name, meeting_date: '1900-01-01' };
try {
  const r = JSON.parse($json.choices[0].message.content);
  if (!r.skip && r.title && /^\d{4}-\d{2}-\d{2}$/.test(r.meeting_date || '') && Array.isArray(r.points) && r.points.length) {
    out = { action: 'insert', client_id: src.client_id, client_name: src.client_name, slug: src.slug, title: String(r.title).slice(0, 120), meeting_date: r.meeting_date, points: r.points.map(p => String(p)) };
  }
} catch (e) {}
if (!sd.processed.includes(src.docId)) sd.processed.push(src.docId);
return { json: out };

const parsed = $('Parse Summary').all();
const checks = $input.all();
const out = [];
for (let i = 0; i < checks.length; i++) {
  const p = (parsed[i] || {}).json || {};
  const alreadyExists = !!(checks[i].json && checks[i].json.id);
  if (p.action === 'insert' && !alreadyExists) out.push({ json: p });
}
return out;

